insert into public.documents (kind, slug, title, summary, body_md, pinned, period_start, period_end, status, published_at)
values ('weekly', 'week-2', 'Week 2 Report', 'The plan, your feedback and the decisions it led to, the prototype''s new design, and what''s waiting on you.', $md$The plan for the next stage is written, and it has already been through a round of your feedback. The prototype has a cleaner design and proper branding. And the documents, questions and progress now have a private home that only you and I can open.

## What got done

- **The Blueprint.** Written, shared, then updated after your replies. The Updates list on the Progress page says exactly what changed.
- **Decisions recorded from your replies.** UK hosting; what councils can and can't do; the pilot stage; and measuring days until a council marks a report cleared.
- **The prototype.** A cleaner, more modern design with light and dark modes, the Resolve logo and app icons, and a map that works from anywhere. The live demo is on the Progress page.
- **A private portal.** One place for the Blueprint, the progress log, the weekly reports, the questions and the decisions, with a sign-in for you and one for me.

## Decisions made this week

- The data is hosted in the UK.
- Each council only sees reports for its own area, and a Resolve view sees everything.
- Councils can acknowledge, schedule and clear, but they can't verify.
- The routing and checking stage is the pilot.
- Councils are measured on days until they mark a report cleared, not days until it's verified.
- Councils and contractors are approached once there's a prototype that looks good and works.

## Waiting on you

These are on the Questions page:

- Whether 5 confirmed agreements, each with a photo, is the right rule for a fix to count as verified, and who checks each photo.
- What should happen when someone disagrees and sends a photo.
- What to do in a remote area where 5 residents may never reply.
- Whether to start the pilot in Colchester, which has two levels of council, or in Huddersfield, which has one.
- What the plan for testing Resolve UK is.

## Next

- Confirm the verification rule with you, so the pilot stage can be sized properly.
- Start the Foundation stage: the database in the UK, the wider set of issue types, and smaller photos.
- [Anything else planned for next week.]

## Time

[Hours spent this week, and how they compare with the estimate in the Blueprint.]
$md$, false, '2026-09-19', '2026-09-25', 'draft', null)
on conflict (slug) do nothing;

insert into public.questions (document_id, key, prompt, why, note, position, status)
select d.id, 'q1', 'Who will check the dashboard at the start, and who marks a report as cleared: your team or the council''s staff?', 'This tells me who needs a login.', 'Answered by email on 20 September: each council sees only its own area, a Resolve view sees everything, and councils can acknowledge, schedule and clear but not verify.', 1, 'closed'
from public.documents d where d.slug = 'blueprint'
on conflict (key) do nothing;

insert into public.questions (document_id, key, prompt, why, note, position, status)
select d.id, 'q2', 'How do you plan to approach a council, and do you have a contact or a way in?', 'Reports only get fixed if a council takes part.', 'Answered by email on 20 September: councils and contractors will be approached once there''s a prototype that looks good and works, and you can usually get a meeting.', 2, 'closed'
from public.documents d where d.slug = 'blueprint'
on conflict (key) do nothing;

