select d.id, 'q3', 'What is the plan for testing Resolve UK?', 'This helps me decide where to start.', null, 3, 'open'
from public.documents d where d.slug = 'blueprint'
on conflict (key) do nothing;

insert into public.questions (document_id, key, prompt, why, note, position, status)
select d.id, 'q4', 'Should a report count as verified after 5 people agree, each with a photo, and who should check each photo: the AI, a Resolve reviewer, or both?', 'This sets how much checking falls on your team, and what "verified" means in the figures.', null, 4, 'open'
from public.documents d where d.slug = 'blueprint'
on conflict (key) do nothing;

insert into public.questions (document_id, key, prompt, why, note, position, status)
select d.id, 'q5', 'If someone disagrees and sends a photo, should a Resolve reviewer check it and send the report back to the council if it''s right?', 'Some people disagree just to be difficult, so a single complaint shouldn''t reopen a fix.', null, 5, 'open'
from public.documents d where d.slug = 'blueprint'
on conflict (key) do nothing;

insert into public.questions (document_id, key, prompt, why, note, position, status)
select d.id, 'q6', 'In a remote area where 5 residents may never reply, should a Resolve reviewer be able to verify a fix from one clear photo?', 'Otherwise a fix in a quiet area could stay unverified forever.', null, 6, 'open'
from public.documents d where d.slug = 'blueprint'
