insert into public.questions (document_id, key, prompt, why, note, position, status)
select d.id, 'q7', 'Colchester has two levels of council, so a report there may need routing to two places. Are you happy to start there, or should Huddersfield go first?', 'Two levels means two routes to set up, which is a little more work. The plan already allows for it, and I still need to check who covers what.', null, 7, 'open'
from public.documents d where d.slug = 'blueprint'
on conflict (key) do nothing;

