insert into public.updates (title, summary, details_md, released_on, version, demo_url, status)
select 'First working prototype', 'Report a problem with a photo, a category and a location, and see it in a list. It installs on a phone like an app.', $md$You can now:

- Open the prototype on a phone and add it to the home screen.
- Report a problem: pick a type, describe it, add a photo, and mark the location using the phone or a map pin.
- See every report in a list with its photo and status.

Every report shows "Reported" for now, because no council is connected yet.$md$, '2026-09-18', 'v0.1', null, 'published'
where not exists (select 1 from public.updates where title = 'First working prototype');

insert into public.updates (title, summary, details_md, released_on, version, demo_url, status)
select 'Cleaner design and branding', 'A more modern look with light and dark modes, the Resolve logo and app icons, and a map that works from anywhere.', $md$What changed:

- A cleaner layout with a simpler form, clearer buttons and a dropdown that looks the same on every device.
- Light and dark modes that follow the phone's setting.
- The Resolve logo in the header, and proper app icons for the home screen.
- The map opens on a world view, so it works wherever someone is.$md$, '2026-09-19', 'v0.2', null, 'published'
where not exists (select 1 from public.updates where title = 'Cleaner design and branding');

insert into public.updates (title, summary, details_md, released_on, version, demo_url, status)
select 'Blueprint, first version', 'The plan for the next stage, with the questions that needed your help.', $md$Covers how a report moves from a phone to a confirmed fix, what gets built and in what order, rough timings, and your questions answered.$md$, '2026-09-19', null, null, 'published'
where not exists (select 1 from public.updates where title = 'Blueprint, first version');

insert into public.updates (title, summary, details_md, released_on, version, demo_url, status)
select 'Blueprint updated with your answers', 'Your decisions from 20 September are now in the plan.', $md$What changed:

- **Hosting.** UK hosting is decided.
- **Who can do what.** Councils see only their own area and can acknowledge, schedule and clear, but not verify. A Resolve view sees everything and can verify without changing what a council did.
- **How a fix is checked.** The public is shown that a report is cleared and asked whether they agree, with a photo. Disagreeing without a photo doesn't send it back. Five confirmations is the draft rule.
- **The pilot.** Routing and checking fixes is now called out as the pilot stage.
- **Measuring councils.** The measure stops at "cleared", not "verified".
- **The AI step.** The diagram now says it is the AI being confident in its suggestion.
- **Decisions.** The decisions that can wait now have their own page, so they aren't forgotten.$md$, '2026-09-20', null, null, 'published'
where not exists (select 1 from public.updates where title = 'Blueprint updated with your answers');

insert into public.updates (title, summary, details_md, released_on, version, demo_url, status)
select 'Private portal', 'One private place for the Blueprint, progress, weekly reports, questions and decisions, with a sign-in for you and one for me.', $md$Your answers are saved to your account, so you can see them from any of your devices and go back to check earlier ones. Replies from me appear underneath.$md$, '2026-09-20', null, null, 'draft'
where not exists (select 1 from public.updates where title = 'Private portal');

